function exc_out(array $d,int $s=200):never{http_response_code($s);echo json_encode($d,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function exc_can_write(array $u):bool{if(($u['role']??'')==='Super Admin')return true;$p=$u['permissions']['Accounts']??null;if($p==='all')return true;if(!is_array($p))return false;if(in_array('Create',$p,true)||in_array('Edit',$p,true)||in_array('Approve',$p,true))return true;foreach($p as $a)if(is_array($a)&&(in_array('Create',$a,true)||in_array('Edit',$a,true)||in_array('Approve',$a,true)))return true;return false;}
function exc_def():array{return ['revision'=>0,'journals'=>[],'exportCandidates'=>[],'inventoryCostRates'=>[],'localSalesCostRates'=>[]];}
function exc_read():array{tt_ensure_data_dir();if(!is_file(TT_EXC_FILE))return exc_def();$h=fopen(TT_EXC_FILE,'r');if($h===false||!flock($h,LOCK_SH))throw new RuntimeException('Accounts storage unavailable.');try{$raw=stream_get_contents($h);}finally{flock($h,LOCK_UN);fclose($h);}$v=$raw?json_decode($raw,true):null;return is_array($v)?array_replace_recursive(exc_def(),$v):exc_def();}
function exc_names():array{$raw=is_file(TT_EXC_MASTER)?file_get_contents(TT_EXC_MASTER):false;$m=$raw?json_decode($raw,true):null;if(!is_array($m))throw new RuntimeException('Accounting master unavailable.');$o=[];foreach((array)($m['chart']??[]) as $a)if(is_array($a)&&isset($a['code']))$o[(string)$a['code']]=(string)($a['name']??$a['code']);return $o;}
function exc_line(string $a,float $dr,float $cr,array $names,array $extra=[]):array{if(!isset($names[$a]))exc_out(['ok'=>false,'error'=>'Approved account '.$a.' is unavailable.'],422);return array_merge(['account'=>$a,'accountName'=>$names[$a],'debit'=>round($dr,2),'credit'=>round($cr,2)],$extra);}
function exc_date(string $v):string{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$v))exc_out(['ok'=>false,'error'=>'Valid date required.'],422);return $v;}
function exc_entity(string $v):string{$v=strtoupper(trim($v));if(!in_array($v,['TTI','BRM','TG'],true))exc_out(['ok'=>false,'error'=>'Company must be TTI, BRM or TG.'],422);return $v;}
function exc_next(array $items,string $p):string{$n=count($items)+1;do{$id=$p.'-'.gmdate('Y').'-'.str_pad((string)$n,6,'0',STR_PAD_LEFT);$n++;}while(isset($items[$id]));return $id;}
function exc_norm(string $v):string{return strtoupper(trim(preg_replace('/\s+/',' ',$v)??$v));}
function exc_rates(array $s):array{$rows=[];foreach((array)($s['localSalesCostRates']??[]) as $r)if(is_array($r))$rows[]=array_merge($r,['rateSource'=>'Legacy Local Cost']);foreach((array)($s['inventoryCostRates']??[]) as $r)if(is_array($r))$rows[]=array_merge($r,['rateSource'=>'Shared Stock Cost']);return $rows;}
function exc_rate_for(array $s,string $entity,string $product,string $date):?array{$best=null;$pn=exc_norm($product);foreach(exc_rates($s) as $r){if(($r['status']??'Active')!=='Active'||($r['entity']??'')!==$entity||exc_norm((string)($r['product']??''))!==$pn)continue;$from=(string)($r['effectiveFrom']??'');if($from===''||$from>$date)continue;$rank=($r['rateSource']??'')==='Shared Stock Cost'?2:1;$bestRank=$best?(int)($best['_rank']??0):0;if($best===null||$from>(string)$best['effectiveFrom']||($from===(string)$best['effectiveFrom']&&$rank>$bestRank)){$best=$r;$best['_rank']=$rank;}}return $best;}
function exc_is_sale(array $c):bool{return in_array((string)($c['candidateType']??''),['CUSTOMER_EXPORT_SALE','TG_PAKISTAN_INTERCOMPANY'],true);}
function exc_tg_link(array $s,array $c):?array{$pid=trim((string)($c['tgPayableCandidateId']??''));if($pid!==''&&is_array($s['exportCandidates'][$pid]??null))return $s['exportCandidates'][$pid];$source=(string)($c['sourceKey']??'');foreach((array)($s['exportCandidates']??[]) as $x)if(is_array($x)&&($x['candidateType']??'')==='TG_INTERCOMPANY_PAYABLE'&&($x['sourceKey']??'')===$source)return $x;return null;}
function exc_cost_info(array $s,array $c):array{$entity=(string)($c['entity']??'');$date=(string)($c['recognitionDate']??$c['suggestedRecognitionDate']??'');$product=trim((string)($c['meta']['product']??''));$kg=round((float)($c['meta']['actualQtyMT']??0)*1000,3);if($entity==='TG'&&($c['candidateType']??'')==='CUSTOMER_EXPORT_SALE'){$p=exc_tg_link($s,$c);if($p){if(empty($p['journalId']))return ['ready'=>false,'status'=>'Cost Waiting','reason'=>'TG Pakistan purchase cost is still waiting for Accounts approval.','product'=>$product,'kg'=>$kg,'method'=>'TG_LINKED'];$acct=(string)($p['costAccount']??'');$amount=round((float)($p['functionalAmount']??0),2);if($acct==='5100')return ['ready'=>true,'alreadyPosted'=>true,'status'=>'Cost already recognized','product'=>$product,'kg'=>$kg,'amount'=>$amount,'inventoryAccount'=>'','linkedJournalId'=>(string)$p['journalId'],'linkedCandidateId'=>(string)$p['id'],'method'=>'TG_LINKED_DIRECT_COS'];if(in_array($acct,['1310','1320'],true)&&$amount>0)return ['ready'=>true,'status'=>'Ready to Post','product'=>$product,'kg'=>$kg,'amount'=>$amount,'inventoryAccount'=>$acct,'linkedJournalId'=>(string)$p['journalId'],'linkedCandidateId'=>(string)$p['id'],'method'=>'TG_LINKED_INVENTORY'];return ['ready'=>false,'status'=>'Cost Waiting','reason'=>'TG linked purchase cost classification is incomplete.','product'=>$product,'kg'=>$kg,'method'=>'TG_LINKED'];}}
$rate=exc_rate_for($s,$entity,$product,$date);if(!$rate)return ['ready'=>false,'status'=>'Cost Waiting','reason'=>'No stock cost saved for '.$product.' on '.$date.'.','product'=>$product,'kg'=>$kg,'method'=>'RATE'];$cost=round((float)($rate['costPerKg']??0),6);$inv=(string)($rate['inventoryAccount']??'');if($cost<=0||!in_array($inv,['1310','1320','1330'],true))return ['ready'=>false,'status'=>'Cost Waiting','reason'=>'The saved stock cost needs correction.','product'=>$product,'kg'=>$kg,'method'=>'RATE'];return ['ready'=>$kg>0,'status'=>$kg>0?'Ready to Post':'Cost Waiting','reason'=>$kg>0?'':'Actual shipped quantity is missing.','product'=>$product,'kg'=>$kg,'costPerKg'=>$cost,'amount'=>round($kg*$cost,2),'inventoryAccount'=>$inv,'rateId'=>(string)($rate['id']??''),'rateSource'=>(string)($rate['rateSource']??''),'method'=>'RATE'];}
function exc_waiting(array $s,?string $entity=null):array{$o=[];foreach((array)($s['exportCandidates']??[]) as $c){if(!is_array($c)||!exc_is_sale($c)||empty($c['journalId'])||!empty($c['costJournalId']))continue;if($entity!==null&&($c['entity']??'')!==$entity)continue;$info=exc_cost_info($s,$c);$o[]=array_merge($c,['costInfo'=>$info,'costOfSalesStatus'=>$info['status']]);}usort($o,static fn($a,$b)=>strcmp((string)($b['recognitionDate']??''),(string)($a['recognitionDate']??'')));return $o;}
function exc_recent(array $s,?string $entity=null):array{$o=[];foreach((array)($s['exportCandidates']??[]) as $c){if(!is_array($c)||!exc_is_sale($c)||empty($c['costJournalId']))continue;if($entity!==null&&($c['entity']??'')!==$entity)continue;$o[]=$c;}usort($o,static fn($a,$b)=>strcmp((string)($b['costPostedAt']??''),(string)($a['costPostedAt']??'')));return array_slice($o,0,30);}
function exc_payload(array $s,?string $entity=null):array{$rates=array_values(array_filter(exc_rates($s),static fn($r)=>$entity===null||($r['entity']??'')===$entity));usort($rates,static fn($a,$b)=>strcmp((string)($b['effectiveFrom']??''),(string)($a['effectiveFrom']??'')));return ['ok'=>true,'waiting'=>exc_waiting($s,$entity),'recent'=>exc_recent($s,$entity),'rates'=>$rates,'serverNow'=>gmdate('c')];}
function exc_post(array &$s,array $names,array $u,?string $only=null):array{$posted=[];$skipped=[];foreach((array)$s['exportCandidates'] as $id=>$c){if(!is_array($c)||!exc_is_sale($c)||empty($c['journalId'])||!empty($c['costJournalId']))continue;if($only!==null&&$id!==$only)continue;$info=exc_cost_info($s,$c);if(empty($info['ready'])){$skipped[]=['id'=>$id,'reason'=>$info['reason']??'Cost is not ready.'];continue;}if(!empty($info['alreadyPosted'])){$s['exportCandidates'][$id]['costJournalId']=$info['linkedJournalId'];$s['exportCandidates'][$id]['costOfSalesStatus']='Cost already recognized from TG intercompany purchase';$s['exportCandidates'][$id]['costAmount']=$info['amount'];$s['exportCandidates'][$id]['costMethod']=$info['method'];$s['exportCandidates'][$id]['costPostedAt']=gmdate('c');$posted[]=['candidateId'=>$id,'journalId'=>$info['linkedJournalId'],'amount'=>$info['amount'],'reused'=>true];continue;}$amount=round((float)($info['amount']??0),2);$inv=(string)($info['inventoryAccount']??'');if($amount<=0||!in_array($inv,['1310','1320','1330'],true)){$skipped[]=['id'=>$id,'reason'=>'Cost amount or stock type is invalid.'];continue;}$jid=exc_next((array)$s['journals'],'AUTO');$product=(string)($info['product']??$c['meta']['product']??'');$extra=['exportCandidateId'=>$id,'contractRef'=>(string)($c['meta']['contractRef']??''),'lotRef'=>(string)($c['meta']['lotRef']??$c['reference']??''),'product'=>$product,'shippedKg'=>(float)($info['kg']??0),'costMethod'=>(string)($info['method']??'RATE')];if(isset($info['costPerKg']))$extra['costPerKg']=$info['costPerKg'];if(isset($info['rateId']))$extra['costRateId']=$info['rateId'];if(isset($info['linkedCandidateId']))$extra['linkedCandidateId']=$info['linkedCandidateId'];$lines=[exc_line('5100',$amount,0,$names,$extra),exc_line($inv,0,$amount,$names,$extra)];$date=(string)($c['recognitionDate']??$c['suggestedRecognitionDate']??'');$s['journals'][$jid]=['id'=>$jid,'entity'=>(string)$c['entity'],'date'=>$date,'sourceType'=>'EXPOR